const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMapUnmanaged = std.HashMapUnmanaged;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;

pub const QSM = struct {
    allocator: Allocator,
    contexts: ArrayList([]f64),
    interference: f64,

    pub fn init(allocator: Allocator) QSM {
        return .{
            .allocator = allocator,
            .contexts = ArrayList([]f64).init(allocator),
            .interference = 0.0,
        };
    }

    pub fn deinit(self: *QSM) void {
        for (self.contexts.items) |ctx| {
            self.allocator.free(ctx);
        }
        self.contexts.deinit();
    }

    pub fn multiplex(self: *QSM, synapse: f64, contexts: []const []const f64) !void {
        self.interference = 0.0;
        for (contexts) |ctx| {
            var phase: f64 = 0.0;
            var amp: f64 = 0.0;
            for (ctx) |c| {
                phase += math.pi * c;
                amp += c / 10.0;
            }
            self.interference += math.sin(phase + 0.1) * amp;
        }
        self.interference *= synapse;
    }

    pub fn getInterference(self: *const QSM) f64 {
        return self.interference;
    }
};

pub const MES = struct {
    allocator: Allocator,
    codec: *const fn (allocator: Allocator, str: []const u8) anyerror![]u8,
    condition: bool,

    pub fn init(allocator: Allocator) MES {
        return .{
            .allocator = allocator,
            .codec = &defaultCodec,
            .condition = false,
        };
    }

    pub fn deinit(self: *MES) void {
        _ = self;
    }

    pub fn selfOverwrite(self: *MES, cond: bool) void {
        self.condition = cond;
    }

    pub fn process(self: *MES, input: []const u8) anyerror![]u8 {
        if (self.condition) {
            return try reverseString(self.allocator, input);
        } else {
            return try self.codec(self.allocator, input);
        }
    }

    fn defaultCodec(allocator: Allocator, input: []const u8) anyerror![]u8 {
        const result = try allocator.alloc(u8, input.len);
        @memcpy(result, input);
        return result;
    }

    fn reverseString(allocator: Allocator, s: []const u8) anyerror![]u8 {
        const len = s.len;
        const result = try allocator.alloc(u8, len);
        var i: usize = 0;
        while (i < len) : (i += 1) {
            result[i] = s[len - 1 - i];
        }
        return result;
    }
};

pub const EHM = struct {
    allocator: Allocator,
    state: f64,
    reflection: []u8,

    pub fn init(allocator: Allocator) EHM {
        return .{
            .allocator = allocator,
            .state = 1.0,
            .reflection = &.{},
        };
    }

    pub fn deinit(self: *EHM) void {
        self.allocator.free(self.reflection);
    }

    pub fn update(self: *EHM, refl: []const u8) anyerror!void {
        self.allocator.free(self.reflection);
        self.reflection = try self.allocator.dupe(u8, refl);
        self.state *= 1.1;
    }

    pub fn getState(self: *const EHM) f64 {
        return self.state;
    }
};

pub const MXSI = struct {
    voltage: f64,
    temp: f64,
    conductance: f64,

    pub fn init() MXSI {
        return .{
            .voltage = 0.0,
            .temp = 300.0,
            .conductance = 0.0,
        };
    }

    pub fn compute(self: *MXSI, v: f64, t: f64) void {
        self.voltage = v;
        self.temp = t;
        self.conductance = v / (1.0 + t / 300.0);
    }

    pub fn getConductance(self: *const MXSI) f64 {
        return self.conductance;
    }
};

pub const CPS = struct {
    allocator: Allocator,
    thoughts: ArrayList([]u8),
    topology: ArrayList(struct { thought: []u8, phase: f64 }),

    pub fn init(allocator: Allocator) CPS {
        return .{
            .allocator = allocator,
            .thoughts = ArrayList([]u8).init(allocator),
            .topology = ArrayList(struct { thought: []u8, phase: f64 }).init(allocator),
        };
    }

    pub fn deinit(self: *CPS) void {
        for (self.thoughts.items) |t| {
            self.allocator.free(t);
        }
        self.thoughts.deinit();
        for (self.topology.items) |top| {
            self.allocator.free(top.thought);
        }
        self.topology.deinit();
    }

    pub fn addThought(self: *CPS, thought: []const u8) anyerror!void {
        const dup = try self.allocator.dupe(u8, thought);
        try self.thoughts.append(dup);
    }

    pub fn computeTopology(self: *CPS) anyerror!void {
        self.topology.clearAndFree();
        for (self.thoughts.items) |th| {
            const len = th.len;
            const phase = math.sqrt(@as(f64, @floatFromInt(len)));
            const dup_th = try self.allocator.dupe(u8, th);
            const top = .{ .thought = dup_th, .phase = phase };
            try self.topology.append(top);
        }
    }

    pub fn getTopology(self: *const CPS) []const struct { thought: []u8, phase: f64 } {
        return self.topology.items;
    }
};

pub const TensorCore = struct {
    allocator: Allocator,
    shape: []usize,
    data: []f64,
    dtype: DType,
    qsm: QSM,
    mes: MES,
    ehm: EHM,
    mxsi: MXSI,
    cps: CPS,

    pub const DType = enum { f64, f32, i64, i32 };

    pub fn init(allocator: Allocator, shape: []const usize, dtype: DType) anyerror!TensorCore {
        const total_size = blk: {
            var size: usize = 1;
            for (shape) |dim| {
                size = try std.math.mul(usize, size, dim);
            }
            break :blk size;
        };
        const data = try allocator.alloc(f64, total_size);
        @memset(data, 0.0);
        var qsm = QSM.init(allocator);
        var mes = MES.init(allocator);
        var ehm = EHM.init(allocator);
        var mxsi = MXSI.init();
        var cps = CPS.init(allocator);
        var tensor = TensorCore{
            .allocator = allocator,
            .shape = try allocator.dupe(usize, shape),
            .data = data,
            .dtype = dtype,
            .qsm = qsm,
            .mes = mes,
            .ehm = ehm,
            .mxsi = mxsi,
            .cps = cps,
        };
        return tensor;
    }

    pub fn deinit(self: *TensorCore) void {
        self.qsm.deinit();
        self.mes.deinit();
        self.ehm.deinit();
        self.cps.deinit();
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
    }

    pub fn reshape(self: *TensorCore, new_shape: []const usize) anyerror!void {
        const old_total = blk: {
            var size: usize = 1;
            for (self.shape) |dim| {
                size = try std.math.mul(usize, size, dim);
            }
            break :blk size;
        };
        const new_total = blk: {
            var size: usize = 1;
            for (new_shape) |dim| {
                size = try std.math.mul(usize, size, dim);
            }
            break :blk size;
        };
        if (old_total != new_total) {
            return error.InvalidShape;
        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(usize, new_shape);
    }

    pub fn add(self: *TensorCore, other: *const TensorCore) anyerror!void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* += o;
        }
    }

    pub fn mul(self: *TensorCore, other: *const TensorCore) anyerror!void {
        if (!self.shapeMatches(other)) return error.ShapeMismatch;
        for (self.data, other.data) |*val, o| {
            val.* *= o;
        }
    }

    pub fn matmul(self: *const TensorCore, other: *const TensorCore, allocator: Allocator) anyerror!TensorCore {
        if (self.shape.len != 2 or other.shape.len != 2) return error.NotMatrix;
        if (self.shape[1] != other.shape[0]) return error.InvalidDimensions;
        const rows = self.shape[0];
        const cols = other.shape[1];
        const inner = self.shape[1];
        var result = try TensorCore.init(allocator, &[_]usize{ rows, cols }, .f64);
        for (0..rows) |i| {
            for (0..cols) |j| {
                var sum: f64 = 0.0;
                for (0..inner) |k| {
                    sum += self.data[i * inner + k] * other.data[k * cols + j];
                }
                result.data[i * cols + j] = sum;
            }
        }
        return result;
    }

    pub fn softmax(self: *TensorCore, axis: usize) anyerror!void {
        if (self.shape.len != 2) return error.Not2D;
        const rows = self.shape[0];
        const cols = self.shape[1];
        if (axis == 0) {
            for (0..cols) |j| {
                var max_val: f64 = -math.inf(f64);
                var exp_sum: f64 = 0.0;
                for (0..rows) |i| {
                    max_val = math.max(max_val, self.data[i * cols + j]);
                }
                for (0..rows) |i| {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                if (exp_sum != 0.0) {
                    const inv_sum = 1.0 / exp_sum;
                    for (0..rows) |i| {
                        self.data[i * cols + j] *= inv_sum;
                    }
                }
            }
        } else {
            for (0..rows) |i| {
                var max_val: f64 = -math.inf(f64);
                var exp_sum: f64 = 0.0;
                for (0..cols) |j| {
                    max_val = math.max(max_val, self.data[i * cols + j]);
                }
                for (0..cols) |j| {
                    const shifted = self.data[i * cols + j] - max_val;
                    const exp_val = math.exp(shifted);
                    self.data[i * cols + j] = exp_val;
                    exp_sum += exp_val;
                }
                if (exp_sum != 0.0) {
                    const inv_sum = 1.0 / exp_sum;
                    for (0..cols) |j| {
                        self.data[i * cols + j] *= inv_sum;
                    }
                }
            }
        }
    }

    pub fn integrateQSM(self: *TensorCore, synapse: f64, contexts: [][]const f64) anyerror!void {
        try self.qsm.multiplex(synapse, contexts);
        const interf = self.qsm.getInterference();
        for (self.data) |*val| {
            val.* += interf;
        }
    }

    pub fn applyMES(self: *TensorCore, cond: bool, input_str: []const u8) anyerror!void {
        self.mes.selfOverwrite(cond);
        const processed = try self.mes.process(input_str);
        defer self.allocator.free(processed);
        for (self.data) |*val| {
            val.* += @as(f64, @floatFromInt(processed.len)) * 0.01;
        }
    }

    pub fn reflectEHM(self: *TensorCore, refl: []const u8) anyerror!void {
        try self.ehm.update(refl);
        const state = self.ehm.getState();
        for (self.data) |*val| {
            val.* *= state;
        }
    }

    pub fn adjustMXSI(self: *TensorCore, v: f64, t: f64) void {
        self.mxsi.compute(v, t);
        const cond = self.mxsi.getConductance();
        for (self.data) |*val| {
            val.* *= cond;
        }
    }

    pub fn phaseCPS(self: *TensorCore, thoughts: [][]const u8) anyerror!void {
        self.cps.thoughts.clearAndFree();
        for (thoughts) |th| {
            try self.cps.addThought(th);
        }
        try self.cps.computeTopology();
        const topology = self.cps.getTopology();
        var sum_phase: f64 = 0.0;
        for (topology) |top| {
            sum_phase += top.phase;
        }
        if (topology.len > 0) {
            for (self.data) |*val| {
                val.* += sum_phase / @as(f64, @floatFromInt(topology.len));
            }
        }
    }

    fn shapeMatches(self: *const TensorCore, other: *const TensorCore) bool {
        if (self.shape.len != other.shape.len) return false;
        for (self.shape, other.shape) |s, o| {
            if (s != o) return false;
        }
        return true;
    }

    pub fn print(self: *const TensorCore) void {
        std.debug.print("Tensor shape: {any}\n", .{self.shape});
        if (self.shape.len == 2) {
            const rows = self.shape[0];
            const cols = self.shape[1];
            for (0..rows) |i| {
                std.debug.print("[", .{});
                for (0..cols) |j| {
                    std.debug.print("{d:.4}", .{self.data[i * cols + j]});
                    if (j < cols - 1) std.debug.print(", ", .{});
                }
                std.debug.print("]\n", .{});
            }
        }
    }

    pub const SecurityProof = struct {
        pub fn fmrnSecurity(self: *const TensorCore) bool {
            for (self.data) |val| {
                if (val < -1000000 or val > 1000000) return false;
            }
            return true;
        }

        pub fn harmonyPositive(self: *const TensorCore) bool {
            var sum: f64 = 0.0;
            for (self.data) |val| {
                sum += math.fabs(val);
            }
            return sum > 0.0;
        }

        pub fn memorySafe(self: *const TensorCore) bool {
            return self.shape.len > 0 and self.data.len > 0;
        }

        pub fn convergence(self: *const TensorCore) bool {
            var sum_sq: f64 = 0.0;
            for (self.data) |val| {
                sum_sq += val * val;
            }
            return sum_sq < 1e6;
        }
    };
};

pub fn main() anyerror!void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var a = try TensorCore.init(allocator, &[_]usize{ 2, 3 }, .f64);
    defer a.deinit();
    a.data[0] = 1.0;
    a.data[1] = 2.0;
    a.data[2] = 3.0;
    a.data[3] = 4.0;
    a.data[4] = 5.0;
    a.data[5] = 6.0;

    var b = try TensorCore.init(allocator, &[_]usize{ 3, 2 }, .f64);
    defer b.deinit();
    b.data[0] = 1.0;
    b.data[1] = 2.0;
    b.data[2] = 3.0;
    b.data[3] = 4.0;
    b.data[4] = 5.0;
    b.data[5] = 6.0;

    var c = try a.matmul(&b, allocator);
    defer c.deinit();
    c.print();

    try a.softmax(1);
    a.print();

    try a.integrateQSM(1.0, &[_][]const f64{ &[_]f64{ 1.0, 2.0 }, &[_]f64{3.0} });
    a.print();

    try a.applyMES(true, "test");
    try a.reflectEHM("reflect");
    a.adjustMXSI(1.0, 300.0);
    try a.phaseCPS(&[_][]const u8{ "thought1", "thought2" });

    const proof = TensorCore.SecurityProof{};
    _ = proof.fmrnSecurity(&a);
    _ = proof.harmonyPositive(&a);
    _ = proof.memorySafe(&a);
    _ = proof.convergence(&a);
}

test "TensorCore matmul" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var a = try TensorCore.init(allocator, &[_]usize{ 2, 3 }, .f64);
    defer a.deinit();
    a.data[0] = 1.0;
    a.data[1] = 2.0;
    a.data[2] = 3.0;
    a.data[3] = 4.0;
    a.data[4] = 5.0;
    a.data[5] = 6.0;

    var b = try TensorCore.init(allocator, &[_]usize{ 3, 2 }, .f64);
    defer b.deinit();
    b.data[0] = 7.0;
    b.data[1] = 8.0;
    b.data[2] = 9.0;
    b.data[3] = 10.0;
    b.data[4] = 11.0;
    b.data[5] = 12.0;

    var c = try a.matmul(&b, allocator);
    defer c.deinit();

    try testing.expectApproxEqAbs(f64, c.data[0], 58.0, 0.0001);
    try testing.expectApproxEqAbs(f64, c.data[1], 64.0, 0.0001);
    try testing.expectApproxEqAbs(f64, c.data[2], 139.0, 0.0001);
    try testing.expectApproxEqAbs(f64, c.data[3], 154.0, 0.0001);
}

